:root {
  --orange: #ff6a1a;
  --orange-soft: #ff934d;
  --cyan: #4fe8ff;
  --cyan-dim: #8ee9f7;
  --ink: #060a11;
  --panel: rgba(7, 13, 23, 0.58);
  --panel-strong: rgba(6, 11, 19, 0.82);
  --line: rgba(255, 255, 255, 0.14);
  --muted: rgba(226, 240, 255, 0.56);
  --ui: 'Rajdhani', 'Segoe UI', system-ui, sans-serif;
  --display: 'Orbitron', 'Rajdhani', sans-serif;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #060a11;
  color: #fff;
  font-family: var(--ui);
  overscroll-behavior: none;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font-family: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

kbd {
  font-family: var(--ui);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.04em;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.9);
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.25);
}

.hidden { display: none !important; }

#game-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

#ui { position: fixed; inset: 0; z-index: 10; pointer-events: none; }

/* ================= BOOT ================= */
#boot {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  background: radial-gradient(circle at 50% 44%, #122234 0%, #070b12 58%, #04070b 100%);
  transition: opacity 0.7s ease;
}
#boot.gone { opacity: 0; pointer-events: none; }
.boot-mark {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(26px, 5vw, 44px);
  letter-spacing: 0.16em;
  color: #fff;
}
.boot-mark span { color: var(--orange); margin-left: 10px; }
.boot-track { width: min(320px, 60vw); height: 2px; background: rgba(255, 255, 255, 0.14); overflow: hidden; }
.boot-track i {
  display: block;
  height: 100%;
  width: 40%;
  background: linear-gradient(90deg, transparent, var(--orange), var(--cyan));
  animation: bootSlide 1.1s ease-in-out infinite;
}
@keyframes bootSlide { 0% { transform: translateX(-110%); } 100% { transform: translateX(340%); } }
.boot-copy { font-size: 12px; letter-spacing: 0.34em; color: var(--muted); font-weight: 600; }

/* ================= HUD ================= */
#hud { position: absolute; inset: 0; }

.hud-top {
  position: absolute;
  top: calc(var(--safe-t) + 20px);
  left: calc(var(--safe-l) + 24px);
  right: calc(var(--safe-r) + 24px);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  pointer-events: none;
}

.hud-brand {
  display: flex;
  align-items: baseline;
  gap: 8px;
  filter: drop-shadow(0 2px 12px rgba(0, 0, 0, 0.6));
}
.brand-mark {
  font-family: var(--display);
  font-weight: 900;
  font-size: 21px;
  letter-spacing: 0.02em;
  color: #fff;
}
.brand-horizon {
  font-family: var(--display);
  font-weight: 900;
  font-size: 12px;
  letter-spacing: 0.28em;
  color: var(--orange);
}
.hud-brand i {
  font-style: normal;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.26em;
  color: var(--muted);
  margin-left: 6px;
  padding-left: 10px;
  border-left: 1px solid var(--line);
}

#race-hud {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  align-items: stretch;
}
.race-block {
  min-width: 118px;
  padding: 8px 16px 9px;
  text-align: center;
  background: linear-gradient(180deg, rgba(10, 17, 28, 0.78), rgba(8, 13, 22, 0.52));
  border: 1px solid var(--line);
  border-top: 2px solid var(--cyan);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.race-block small {
  display: block;
  font-size: 9px;
  letter-spacing: 0.24em;
  font-weight: 700;
  color: var(--muted);
  margin-bottom: 1px;
}
.race-block strong {
  font-family: var(--display);
  font-size: 20px;
  letter-spacing: 0.04em;
  font-variant-numeric: tabular-nums;
  color: #fff;
}
.race-block strong em { font-style: normal; font-size: 11px; color: var(--muted); margin-left: 2px; }
.race-progress { min-width: 130px; }
.race-bar { height: 2px; background: rgba(255, 255, 255, 0.14); margin-top: 5px; overflow: hidden; }
.race-bar i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--orange)); transition: width 0.3s ease; }

/* ---- minimap ---- */
.map-panel { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.map-ring {
  position: relative;
  width: 178px;
  height: 178px;
  border-radius: 50%;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.22);
  outline: 1px solid rgba(0, 0, 0, 0.35);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5), inset 0 0 40px rgba(0, 0, 0, 0.5);
  background: rgba(5, 10, 18, 0.66);
  backdrop-filter: blur(4px);
}
.map-ring canvas { width: 100%; height: 100%; display: block; }
.map-north {
  position: absolute;
  top: 5px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--cyan);
  text-shadow: 0 0 8px rgba(79, 232, 255, 0.7);
}
.map-meta {
  display: flex;
  gap: 10px;
  align-items: baseline;
  font-size: 10px;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.8);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}
.map-meta b { color: var(--cyan); font-family: var(--display); font-size: 10px; }

/* ---- event card ---- */
#event-card {
  position: absolute;
  left: calc(var(--safe-l) + 24px);
  top: calc(var(--safe-t) + 88px);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 11px 16px 11px 0;
  background: linear-gradient(90deg, rgba(8, 14, 24, 0.72), rgba(8, 14, 24, 0.18));
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 0;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}
#event-card.hidden-card { opacity: 0; transform: translateX(-12px); }
.event-accent { width: 3px; align-self: stretch; background: linear-gradient(180deg, var(--orange), transparent); }
.event-copy { display: flex; flex-direction: column; gap: 1px; }
.event-copy small { font-size: 8px; letter-spacing: 0.22em; font-weight: 700; color: var(--orange-soft); }
.event-copy strong { font-family: var(--display); font-size: 13px; letter-spacing: 0.1em; }
.event-copy span { font-size: 11px; color: var(--muted); font-weight: 500; letter-spacing: 0.02em; }
.event-len { display: flex; flex-direction: column; align-items: center; padding-left: 5px; color: var(--muted); }
.event-len b { font-family: var(--display); font-size: 13px; color: #fff; }
.event-len span { font-size: 8px; letter-spacing: 0.16em; }

/* ---- target indicator ---- */
#target-indicator {
  position: absolute;
  top: calc(var(--safe-t) + 94px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  background: rgba(6, 12, 20, 0.6);
  border: 1px solid rgba(79, 232, 255, 0.32);
  border-radius: 30px;
  backdrop-filter: blur(8px);
  color: var(--cyan);
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: 0.08em;
  text-shadow: 0 0 12px rgba(79, 232, 255, 0.4);
}
#target-indicator svg { width: 17px; height: 17px; fill: var(--cyan); filter: drop-shadow(0 0 6px rgba(79, 232, 255, 0.8)); transition: transform 0.1s linear; }
#target-indicator span { color: #dff9ff; }

/* ---- toasts ---- */
#toasts {
  position: absolute;
  top: calc(var(--safe-t) + 180px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: min(420px, 86vw);
  z-index: 20;
}
.toast {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 18px 9px 12px;
  background: linear-gradient(90deg, rgba(7, 13, 22, 0.9), rgba(7, 13, 22, 0.62));
  border: 1px solid rgba(79, 232, 255, 0.28);
  border-left: 3px solid var(--cyan);
  background-clip: padding-box;
  backdrop-filter: blur(10px);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
  animation: toastIn 0.35s cubic-bezier(0.2, 1, 0.4, 1) both;
  white-space: nowrap;
}
.toast.out { animation: toastOut 0.35s ease both; }
.toast.orange { border-color: rgba(255, 122, 26, 0.4); border-left-color: var(--orange); }
.toast.red { border-color: rgba(255, 70, 70, 0.4); border-left-color: #ff4646; }
.toast b { font-family: var(--display); font-size: 12px; letter-spacing: 0.08em; color: #fff; }
.toast span { font-size: 11px; letter-spacing: 0.06em; color: var(--muted); font-weight: 600; }
.toast i { font-style: normal; font-family: var(--display); font-size: 11px; color: var(--cyan); margin-left: auto; }
.toast.orange i { color: var(--orange-soft); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px) scale(0.98); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* ---- drift ---- */
#drift-panel {
  position: absolute;
  left: calc(var(--safe-l) + 26px);
  bottom: calc(var(--safe-b) + 76px);
  width: 186px;
  padding: 10px 14px 11px;
  background: linear-gradient(135deg, rgba(8, 14, 24, 0.78), rgba(8, 14, 24, 0.3));
  border-left: 2px solid var(--orange);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.25s ease, transform 0.25s ease;
}
#drift-panel.active { opacity: 1; transform: none; }
.drift-head { display: flex; justify-content: space-between; align-items: baseline; }
.drift-head span { font-size: 9px; letter-spacing: 0.3em; font-weight: 700; color: var(--orange-soft); }
.drift-head b { font-family: var(--display); font-size: 18px; color: #fff; font-variant-numeric: tabular-nums; }
.drift-meter { height: 3px; background: rgba(255, 255, 255, 0.12); margin-top: 6px; overflow: hidden; }
.drift-meter i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--orange), #ffe3a3); }
#drift-panel small { display: block; margin-top: 4px; font-size: 9px; font-weight: 700; letter-spacing: 0.12em; color: var(--muted); }

/* ---- prompt ---- */
#prompt {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 128px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 20px 10px 12px;
  background: linear-gradient(90deg, rgba(8, 14, 24, 0.88), rgba(8, 14, 24, 0.55));
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-left: 2px solid var(--orange);
  backdrop-filter: blur(10px);
  animation: promptPulse 2s ease-in-out infinite;
  pointer-events: auto;
}
#prompt kbd {
  width: 30px;
  height: 30px;
  font-size: 14px;
  border-color: rgba(255, 255, 255, 0.4);
  background: rgba(255, 255, 255, 0.12);
  border-radius: 6px;
}
#prompt div { display: flex; flex-direction: column; }
#prompt b { font-family: var(--display); font-size: 12px; letter-spacing: 0.1em; }
#prompt span { font-size: 10.5px; letter-spacing: 0.08em; color: var(--muted); font-weight: 600; }
@keyframes promptPulse { 0%, 100% { box-shadow: 0 0 0 rgba(255, 106, 26, 0); } 50% { box-shadow: 0 0 28px rgba(255, 106, 26, 0.18); } }

/* ---- speedometer ---- */
#speedo {
  position: absolute;
  right: calc(var(--safe-r) + 22px);
  bottom: calc(var(--safe-b) + 14px);
  width: 286px;
  height: 212px;
  filter: drop-shadow(0 12px 28px rgba(0, 0, 0, 0.5));
}
#speedo svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
#speedo-track { fill: none; stroke: rgba(255, 255, 255, 0.13); stroke-width: 7; stroke-linecap: round; }
#speedo-fill {
  fill: none;
  stroke: url(#speedGrad);
  stroke-width: 7;
  stroke-linecap: round;
  filter: url(#speedGlow);
  transition: stroke-dashoffset 0.06s linear;
}
#speedo-ticks line { stroke: rgba(255, 255, 255, 0.38); stroke-width: 1.4; }
#speedo-ticks line.major { stroke: rgba(255, 255, 255, 0.7); stroke-width: 2; }
#speedo-ticks text { fill: rgba(255, 255, 255, 0.5); font-family: var(--ui); font-size: 8px; font-weight: 700; letter-spacing: 0.06em; }
.speedo-center {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.speed-value { display: flex; flex-direction: column; align-items: center; line-height: 1; }
.speed-value span {
  font-family: var(--display);
  font-weight: 900;
  font-size: 54px;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
  color: #fff;
  text-shadow: 0 0 26px rgba(120, 220, 255, 0.35);
}
.speed-value small { font-size: 8.5px; font-weight: 700; letter-spacing: 0.34em; color: var(--muted); margin-top: 3px; }
.speed-sub { display: flex; align-items: center; gap: 7px; margin-top: 5px; }
.speed-sub b {
  font-family: var(--display);
  font-size: 12px;
  color: var(--orange-soft);
  border: 1px solid rgba(255, 122, 26, 0.4);
  padding: 1px 6px;
  line-height: 1.2;
}
.speed-sub i { width: 1px; height: 11px; background: var(--line); }
#rpm-bar { display: block; width: 62px; height: 3px; background: rgba(255, 255, 255, 0.16); overflow: hidden; }
#rpm-bar em { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--orange)); transition: width 0.05s linear; }
.nos-bar {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: 6px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nos-bar > span { font-size: 8px; font-weight: 700; letter-spacing: 0.24em; color: var(--cyan); }
.nos-track { width: 108px; height: 4px; background: rgba(255, 255, 255, 0.16); overflow: hidden; transform: skewX(-20deg); }
.nos-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #127d9c, var(--cyan)); box-shadow: 0 0 10px rgba(79, 232, 255, 0.6); }

/* ---- hint bar ---- */
#hint-bar {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: calc(var(--safe-b) + 18px);
  display: flex;
  gap: 16px;
  padding: 6px 16px;
  background: rgba(4, 8, 14, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(6px);
  color: rgba(255, 255, 255, 0.66);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  font-weight: 600;
  white-space: nowrap;
}
#hint-bar span { display: flex; align-items: center; gap: 4px; }
#hint-bar kbd { height: 17px; min-width: 17px; font-size: 9px; border-color: rgba(255, 255, 255, 0.16); background: rgba(255, 255, 255, 0.05); }

/* ================= TOUCH ================= */
#touch-controls { display: none; }
@media (max-width: 900px), (pointer: coarse) {
  #touch-controls {
    display: block;
    position: absolute;
    inset: 0;
    pointer-events: none;
  }
  .touch-btn {
    pointer-events: auto;
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 62px;
    height: 62px;
    border-radius: 50%;
    background: radial-gradient(circle at 40% 35%, rgba(255, 255, 255, 0.16), rgba(6, 12, 20, 0.55) 70%);
    border: 1px solid rgba(255, 255, 255, 0.26);
    backdrop-filter: blur(8px);
    color: #fff;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.35), inset 0 0 18px rgba(255, 255, 255, 0.04);
    transition: transform 0.08s ease, background 0.1s ease;
  }
  .touch-btn svg { width: 26px; height: 26px; }
  .touch-btn.press { transform: scale(0.93); background: rgba(255, 255, 255, 0.24); }
  .steer-pad { position: absolute; left: calc(var(--safe-l) + 14px); bottom: calc(var(--safe-b) + 18px); display: flex; gap: 8px; }
  .pedal-pad { position: absolute; right: calc(var(--safe-r) + 14px); bottom: calc(var(--safe-b) + 18px); display: flex; gap: 8px; }
  .pedal-pad .gas { width: 70px; height: 70px; background: radial-gradient(circle at 40% 35%, rgba(255, 140, 60, 0.34), rgba(20, 10, 5, 0.6) 75%); border-color: rgba(255, 140, 60, 0.5); }
  .pedal-pad .brake { width: 56px; height: 56px; align-self: flex-end; margin-bottom: 4px; }
  .handbrake {
    width: 58px; height: 33px; border-radius: 18px;
    right: calc(var(--safe-r) + 96px);
    bottom: calc(var(--safe-b) + 98px);
    font-size: 9px; font-weight: 700; letter-spacing: 0.14em; color: var(--orange-soft);
    border-color: rgba(255, 122, 26, 0.34);
  }
  .nitro {
    width: 58px; height: 33px; border-radius: 18px;
    left: calc(var(--safe-l) + 96px);
    bottom: calc(var(--safe-b) + 98px);
    font-size: 9px; font-weight: 700; letter-spacing: 0.14em; color: var(--cyan);
    border-color: rgba(79, 232, 255, 0.34);
  }
  .race-touch {
    width: auto; height: 34px; border-radius: 18px; padding: 0 16px;
    left: 50%; transform: translateX(-50%);
    bottom: calc(var(--safe-b) + 194px);
    font-size: 10px; font-weight: 700; letter-spacing: 0.18em;
    color: #fff; border-color: rgba(255, 255, 255, 0.26);
    background: linear-gradient(90deg, rgba(255, 106, 26, 0.7), rgba(255, 150, 60, 0.42));
    display: none;
  }
  .race-touch.show { display: flex; }
  .race-touch.press { transform: translateX(-50%) scale(0.94); }
  #hint-bar { display: none; }
  #prompt { display: none !important; }
  #event-card { top: calc(var(--safe-t) + 74px); left: calc(var(--safe-l) + 14px); padding: 8px 12px 8px 0; }
  .event-copy strong { font-size: 11px; }
  .event-copy span { font-size: 9.5px; }
  .event-len { display: none; }
  .hud-top { top: calc(var(--safe-t) + 14px); left: calc(var(--safe-l) + 14px); right: calc(var(--safe-r) + 14px); }
  .map-ring { width: 116px; height: 116px; }
  .map-meta { font-size: 8px; gap: 6px; }
  .map-meta b { font-size: 8px; }
  .brand-mark { font-size: 16px; }
  .brand-horizon { font-size: 9px; }
  .hud-brand i { display: none; }
  #drift-panel { bottom: calc(var(--safe-b) + 86px); left: calc(var(--safe-l) + 16px); width: 150px; padding: 7px 11px 8px; }
  .drift-head b { font-size: 15px; }
  #speedo { width: 150px; height: 122px; right: auto; left: 50%; transform: translateX(-50%); bottom: calc(var(--safe-b) + 92px); }
  .speedo-center { bottom: 34px; }
  .speed-value span { font-size: 32px; }
  .speed-value small { font-size: 6px; letter-spacing: 0.2em; }
  .speed-sub { margin-top: 2px; gap: 5px; }
  .speed-sub b { font-size: 9px; padding: 0 4px; }
  #rpm-bar { width: 38px; height: 2px; }
  .nos-bar { bottom: 2px; gap: 5px; }
  .nos-bar > span { font-size: 6px; }
  .nos-track { width: 64px; height: 3px; }
  #race-hud { top: calc(var(--safe-t) + 138px); left: 14px; transform: none; }
  .race-block { min-width: 96px; padding: 6px 10px 7px; }
  .race-block strong { font-size: 15px; }
  .race-block small { font-size: 7px; }
  .race-progress { min-width: 100px; }
  #target-indicator { top: calc(var(--safe-t) + 138px); left: auto; right: 14px; transform: none; font-size: 10px; padding: 5px 10px; }
  #toasts { top: calc(var(--safe-t) + 196px); }
  .toast { padding: 7px 13px 7px 10px; }
  .toast b { font-size: 10px; }
  .toast span { font-size: 9px; }
  .speedlines { display: none; }
}

/* ================= TITLE ================= */
#title-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  pointer-events: auto;
  overflow: hidden;
  background: linear-gradient(90deg, rgba(4, 8, 14, 0.92) 0%, rgba(4, 8, 14, 0.74) 35%, rgba(4, 8, 14, 0.22) 66%, rgba(4, 8, 14, 0.08) 100%);
  transition: opacity 0.65s ease, visibility 0.65s;
}
#title-screen::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(4, 8, 14, 0.55), transparent 26%, transparent 68%, rgba(4, 8, 14, 0.85));
  pointer-events: none;
}
#title-screen.leaving { opacity: 0; visibility: hidden; pointer-events: none; }
.title-shade {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 72% 45%, rgba(255, 140, 60, 0.1), transparent 52%),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.016) 0 1px, transparent 1px 3px);
  pointer-events: none;
  mix-blend-mode: screen;
}
.title-top {
  position: absolute;
  top: calc(var(--safe-t) + 24px);
  left: calc(var(--safe-l) + 4vw);
  right: calc(var(--safe-r) + 4vw);
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 2;
  font-size: 10px;
  letter-spacing: 0.24em;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.62);
}
.title-top-brand { font-family: var(--display); font-size: 13px; letter-spacing: 0.14em; color: #fff; }
.title-top-brand span { color: var(--orange); }
.title-top-meta { display: flex; align-items: center; gap: 8px; }
.title-top-meta i { width: 5px; height: 5px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 10px var(--orange); animation: blink 2s ease-in-out infinite; }
@keyframes blink { 50% { opacity: 0.35; } }

.title-content {
  position: relative;
  z-index: 3;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: min(700px, 92vw);
  padding-left: calc(var(--safe-l) + 6vw);
  padding-bottom: 20px;
}
.kicker {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3em;
  color: var(--orange-soft);
  margin-bottom: 18px;
}
.kicker i { width: 26px; height: 1px; background: var(--orange); box-shadow: 0 0 10px rgba(255, 120, 40, 0.7); }

.logo {
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(58px, 9.4vw, 128px);
  line-height: 0.84;
  letter-spacing: -0.03em;
  display: flex;
  flex-direction: column;
  text-transform: uppercase;
  filter: drop-shadow(0 10px 46px rgba(0, 0, 0, 0.55));
}
.logo span {
  background: linear-gradient(100deg, #fff 12%, #d9f4ff 46%, #8fb8c9 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.logo em {
  font-style: normal;
  font-size: 0.52em;
  letter-spacing: 0.26em;
  margin-top: 0.1em;
  color: transparent;
  -webkit-text-stroke: 1.4px rgba(255, 255, 255, 0.62);
  text-shadow: none;
}
.tagline {
  margin-top: 22px;
  font-size: clamp(13px, 1.15vw, 16px);
  line-height: 1.55;
  font-weight: 500;
  letter-spacing: 0.015em;
  color: rgba(227, 241, 255, 0.68);
}
.tagline b { color: rgba(255, 255, 255, 0.92); font-weight: 600; }

.garage-panel {
  margin-top: 26px;
  width: min(430px, 86%);
  padding: 14px 18px 15px;
  background: linear-gradient(120deg, rgba(10, 17, 28, 0.72), rgba(10, 17, 28, 0.26));
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-left: 2px solid var(--orange);
